diff --git a/tests/support/local-app-route.js b/tests/support/local-app-route.js
index ca82c38..215d295 100644
--- a/tests/support/local-app-route.js
+++ b/tests/support/local-app-route.js
@@ -2,12 +2,12 @@ const fs = require('node:fs');
